import { defineQuery } from "groq";

/**
 * All GROQ for the site lives here (CLAUDE.md). Result types are generated by `pnpm typegen`
 * into src/sanity/types.ts. Never hand-write them.
 */

// Image projection: asset ref + hotspot/crop for the URL builder, plus LQIP and dimensions.
const image = /* groq */ `{
  ...,
  "lqip": asset->metadata.lqip,
  "dimensions": asset->metadata.dimensions{ width, height, aspectRatio }
}`;

const workCard = /* groq */ `{
  _id,
  title,
  "slug": slug.current,
  client,
  year,
  services,
  excerpt,
  coverImage${image}
}`;

const journalCard = /* groq */ `{
  _id,
  title,
  "slug": slug.current,
  publishedAt,
  excerpt,
  coverImage${image}
}`;

export const SITE_SETTINGS_QUERY = defineQuery(
  `*[_type == "siteSettings" && _id == "siteSettings"][0]`,
);

export const FEATURED_WORK_QUERY = defineQuery(
  `*[_type == "work" && featured == true && defined(slug.current)] | order(year desc) ${workCard}`,
);

export const ALL_WORK_QUERY = defineQuery(
  `*[_type == "work" && defined(slug.current)] | order(year desc) ${workCard}`,
);

/** ServiceOfferingSection: related work for one service, max 2 items (CLAUDE.md). */
export const WORK_BY_SERVICE_QUERY = defineQuery(
  `*[_type == "work" && $service in services && defined(slug.current)] | order(year desc) [0...2] ${workCard}`,
);

export const WORK_SLUGS_QUERY = defineQuery(
  `*[_type == "work" && defined(slug.current)].slug.current`,
);

export const WORK_QUERY = defineQuery(
  `*[_type == "work" && slug.current == $slug][0]{
    ...,
    "slug": slug.current,
    coverImage${image},
    body[]{ ..., _type == "imageWithAlt" => ${image} }
  }`,
);

/** FeaturedArticlesSection: featured posts first, then the newest. */
export const FEATURED_JOURNAL_QUERY = defineQuery(
  `*[_type == "journal" && defined(slug.current)] | order(featured desc, publishedAt desc) [0...$limit] ${journalCard}`,
);

export const ALL_JOURNAL_QUERY = defineQuery(
  `*[_type == "journal" && defined(slug.current)] | order(publishedAt desc) ${journalCard}`,
);

export const JOURNAL_SLUGS_QUERY = defineQuery(
  `*[_type == "journal" && defined(slug.current)].slug.current`,
);

export const JOURNAL_QUERY = defineQuery(
  `*[_type == "journal" && slug.current == $slug][0]{
    ...,
    "slug": slug.current,
    coverImage${image},
    body[]{ ..., _type == "imageWithAlt" => ${image} }
  }`,
);
